mapper.select:


    p.deleted = FALSE
    AND p.paid_at >= #{timeRange.startAt}
    AND p.paid_at < #{timeRange.endAt}

        AND FALSE

        AND p.counterparty_type = 'SUPPLIER'

            AND (p.counterparty_type = 'SUPPLIER' OR
                 (p.counterparty_type = 'CUSTOMER' AND c.seller_id IN
                    #{sellerId}))


    AND p.id = #{query.paymentId}

        AND p.counterparty_type = #{query.counterpartyType}

    AND p.counterparty_id = #{query.counterpartyId}

        AND p.counterparty_name_snapshot ILIKE CONCAT('%', #{query.counterpartyName}, '%')

    AND p.method = #{query.method}
    AND p.source_type = #{query.sourceType}
    AND p.entry_type = #{query.entryType}

        AND p.entry_type = 'NORMAL'
        AND GREATEST(p.amount - reversed.reversedAmount - used.usedAmount, 0) > 0


ORDER BY p.paid_at DESC, p.id DESC

SELECT * FROM finance_payment
WHERE source_type = #{sourceType}
  AND source_id = #{sourceId}
  AND entry_type = 'NORMAL'
  AND deleted = FALSE
